#include <vector>
#include <algorithm>

class Solution {
public:
    int areaOfMaxDiagonal(std::vector<std::vector<int>>& dimensions) {
        int maxDiagSq = -1;
        int maxArea = 0;
        for (const auto& d : dimensions) {
            int l = d[0], w = d[1];
            int diagSq = l * l + w * w;
            int area = l * w;
            if (diagSq > maxDiagSq) {
                maxDiagSq = diagSq;
                maxArea = area;
            } else if (diagSq == maxDiagSq) {
                maxArea = std::max(maxArea, area);
            }
        }
        return maxArea;
    }
};

